// Live connector tests. MongoDB runs against a real mongod binary (mongodb-memory-server);
// PostgreSQL SQL generated by the connector is executed on pg-mem, an in-process Postgres emulator.
import assert from 'node:assert/strict';
import { after, before, describe, test } from 'node:test';
import { newDb } from 'pg-mem';
import { startApi } from './helpers.js';
import { buildSql } from '../apps/api/src/connectors/postgresql.js';
import { validateSpec } from '../apps/api/src/connectors/querySpec.js';

describe('postgresql query builder on a Postgres engine', () => {
  const mem = newDb();
  mem.public.none(`CREATE TABLE payments (id int, gateway text, status text, amount int);
    INSERT INTO payments VALUES (1,'a','failed',10),(2,'a','success',20),(3,'b','failed',30),(4,'b','failed',5);`);
  const schema = { payments: { fields: ['id', 'gateway', 'status', 'amount'].map((name) => ({ name })) } };
  const run = (spec) => {
    const { text, params } = buildSql(validateSpec(spec, {}, schema));
    let i = 0;
    const inlined = text.replace(/\$\d+/g, () => {
      const v = params[i++];
      return Array.isArray(v) ? `ARRAY[${v.map((x) => `'${x}'`).join(',')}]` : typeof v === 'number' ? String(v) : `'${v}'`;
    });
    return mem.public.many(inlined);
  };

  test('count, aggregate and find execute with the expected results', () => {
    assert.deepEqual(run({ operation: 'count', collection: 'payments', where: [{ field: 'status', op: 'eq', value: 'failed' }] }), [{ count: 3 }]);
    const agg = run({ operation: 'aggregate', collection: 'payments', groupBy: ['gateway'], metrics: [{ op: 'sum', field: 'amount' }], where: [{ field: 'status', op: 'in', value: ['failed'] }] });
    assert.deepEqual(agg.map((r) => [r.gateway, r.count, r.sum_amount]).sort(), [['a', 1, 10], ['b', 2, 35]]);
    const rows = run({ operation: 'find', collection: 'payments', fields: ['id', 'amount'], sort: { field: 'amount', dir: -1 }, limit: 2 });
    assert.deepEqual(rows, [{ id: 3, amount: 30 }, { id: 2, amount: 20 }]);
  });
});

describe('mongodb connector end-to-end', () => {
  let mongod;
  let api;
  let skip = false;

  before(async () => {
    try {
      const { MongoMemoryServer } = await import('mongodb-memory-server');
      mongod = await MongoMemoryServer.create();
    } catch (e) {
      skip = `mongod unavailable: ${e.message}`;
      return;
    }
    const { MongoClient } = await import('mongodb');
    const client = await MongoClient.connect(mongod.getUri());
    await client.db('shop').collection('orders').insertMany(Array.from({ length: 40 }, (_, i) => ({
      status: i % 4 === 0 ? 'cancelled' : 'delivered',
      courier: i % 2 ? 'FastShip' : 'SlowPost',
      reason: i % 4 === 0 ? (i % 8 === 0 ? 'late_delivery' : 'changed_mind') : null,
      total: 100 + i,
    })));
    await client.db('shop').collection('internal_secrets').insertOne({ apiKey: 'do-not-leak' });
    await client.close();
    api = await startApi();
  });

  after(async () => { await api?.close(); await mongod?.stop(); });

  test('connects, discovers schema and investigates live documents', async (t) => {
    if (skip) return t.skip(skip);
    const token = await api.user('mongo@example.com');
    const p = await api.project(token, 'Mongo Shop');
    const created = await api.call('POST', `/api/v1/projects/${p.id}/integrations`, { token, body: { type: 'mongodb', name: 'Shop DB', config: { connectionString: mongod.getUri(), database: 'shop' }, allowedCollections: ['orders'] } });
    assert.equal(created.status, 201);
    assert.equal(created.body.health.ok, true, JSON.stringify(created.body.health));
    assert.deepEqual(Object.keys(created.body.integration.schema), ['orders']);

    const { body } = await api.call('POST', `/api/v1/projects/${p.id}/ask`, { token, body: { question: 'Why are orders getting cancelled?' } });
    assert.ok(body.calculations.some((c) => c.inputs === '10 / 40' && c.result === '25%'), JSON.stringify(body.calculations));
    assert.ok(body.findings.some((f) => f.text.includes('"late_delivery" 5') && f.text.includes('"changed_mind" 5')));
    assert.ok(body.evidence.some((e) => e.kind === 'live_database'));
    assert.ok(!JSON.stringify(body).includes('do-not-leak'));

    const denied = await api.call('POST', `/api/v1/projects/${p.id}/integrations/${created.body.integration.id}/query`, { token, body: { operation: 'find', collection: 'internal_secrets' } });
    assert.equal(denied.status, 403);
  });
});
